import urllib.request
from bs4 import BeautifulSoup

def get_page(url):
    req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
    with urllib.request.urlopen(req) as resp:
        return resp.read().decode("utf-8", errors="ignore")

for artist in ["Fiona+Apple", "Paula+Cole"]:
    html = get_page(f"https://www.robertchristgau.com/get_artist.php?name={artist}")
    soup = BeautifulSoup(html, "html.parser")
    print(f"=== {artist} ===")
    for a in soup.find_all("a"):
        if "get_album" in a.get("href", ""):
            print(a.get_text(), "->", a.find_next_sibling(text=True) or a.parent.get_text())
